-- Upper bounds for columns that had none, so one account cannot store unbounded rows.
-- Ids are generated by the client (about 12 characters); 100 leaves plenty of room.

do $$
declare
  t text;
begin
  foreach t in array array['workspaces', 'tasks', 'event_categories', 'day_categories', 'events', 'finances', 'special_days', 'workspace_notes', 'reminders']
  loop
    execute format('alter table public.%I add constraint %I check (char_length(id) <= 100)', t, t || '_id_length');
  end loop;
end;
$$;

alter table public.tasks add constraint tasks_workspace_id_length check (char_length(workspace_id) <= 100);
alter table public.tasks add constraint tasks_parent_id_length check (parent_id is null or char_length(parent_id) <= 100);
alter table public.workspace_notes add constraint workspace_notes_workspace_id_length check (char_length(workspace_id) <= 100);
alter table public.events add constraint events_category_id_length check (char_length(category_id) <= 100);
alter table public.finances add constraint finances_category_id_length check (char_length(category_id) <= 100);
alter table public.special_days add constraint special_days_category_id_length check (char_length(category_id) <= 100);

alter table public.profiles add constraint profiles_reset_length check (char_length(reset) <= 32);
alter table public.profiles add constraint profiles_sleep_size check (octet_length(sleep::text) <= 4000);
alter table public.profiles add constraint profiles_photo_format check (photo is null or photo ~ '^data:image/(jpeg|png|webp);base64,');

alter table public.events add constraint events_done_size check (octet_length(done::text) <= 200000);
alter table public.events add constraint events_exceptions_size check (exceptions is null or octet_length(exceptions::text) <= 200000);
alter table public.events add constraint events_days_count check (days is null or cardinality(days) <= 7);
